function PatrolMainDialog:LoadScene()
    if not isNull(self.sceneGo) then
        printInfo("PatrolMainDialog sceneGo not null")
        return
    end
    local co = cs_coroutine.start(function ()
        local loader = ResourceModule.LoadBundleSync(self:GetScenePrefabName(), nil, true)
        if loader.IsSuccess then
            table.insert(self.loaderList, loader)
            local go = GameObject.Instantiate(loader.ResultObject)
            go.name = "PatrolScene"
            self.sceneGo = go
        else
            loader:Release(true)
        end
    end)
    table.insert(self.loadCoList, co)
end

function PatrolMainDialog:GetScenePrefabName()
    local floor = MazeMgr.currentFloor
    local suffixName
    if floor <= 15 then
        suffixName = 1
    elseif floor <= 30 then
        suffixName = 2
    elseif floor <= 45 then
        suffixName = 3
    end
    local prefabName = string.format("Scenes/prefab/maze0%s.prefab", suffixName)
    return prefabName
end

function PatrolMainDialog:DisposeLoadRes()
    if not isNull(self.sceneGo)  then
        GameObject.DestroyImmediate(self.sceneGo)
    end
    for k, v in pairs(self.loaderList) do
        if not isNull(v) then
            v:Release(true)
        end
    end
    for k, v in pairs(self.loadCoList) do
        if not isNull(v) then
            cs_coroutine.stop(v)
        end
    end

end

function PatrolMainDialog:PlayChooseAnim(index)
    if isNull(index) then
        CfUtils.PlayAnimator(self.Root, "Cancel")
    else
        local isPatrolEventPanelOpen = KCookie.Get("isPatrolEventPanelOpen")
        if isPatrolEventPanelOpen and isPatrolEventPanelOpen == true then
        else
            CfUtils.PlayAnimator(self.Root, "Choose")
        end
    end
end

function PatrolMainDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self:DisposeLoadRes()
        Events.RemoveListener(Constants.EventNames.PatrolEventMain, self.EventFresh)
        Events.RemoveListener(Constants.EventNames.PatrolEventChoose, self.EventEnterChoose)

        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return PatrolMainDialog